### What the application actually needs

The login use case needs two things: a URL to send the browser to, and, after the callback, a **verified identity** (stable subject id, a verified contact address, a display name). Tokens, JWKS, `audience` and Auth0's claim names are infrastructure details.

### 1. Gateway interface (`src/application/ports/IdentityProvider.ts`)
```typescript
import { Result } from '../shared/Result';

export interface LoginChallenge {
  readonly state: string;        // CSRF protection, stored in the session
  readonly codeVerifier: string; // PKCE secret, stored in the session
}

export interface VerifiedIdentity {
  readonly provider: string;      // "auth0", "okta", "dev"
  readonly subject: string;       // stable id at the provider
  readonly contact: string | null; // only present when the provider verified it
  readonly displayName: string;
}

export type IdentityError =
  | { kind: 'StateMismatch' }
  | { kind: 'CodeRejected'; reason: string }
  | { kind: 'InvalidToken'; reason: string }
  | { kind: 'ProviderUnavailable'; detail: string };

export interface IdentityProvider {
  authorizationUrl(challenge: LoginChallenge, redirectUri: string): Promise<string>;
  complete(
    challenge: LoginChallenge,
    callback: { code: string; state: string },
    redirectUri: string,
  ): Promise<Result<VerifiedIdentity, IdentityError>>;
}
```

The `provider` + `subject` pair is what the application stores to link accounts. It never stores an Auth0 `sub` as a bare string, so moving to Okta can coexist with existing users.

### 2. Auth0 adapter (`src/infrastructure/identity/Auth0IdentityProvider.ts`)
Signature verification is delegated to an injected `IdTokenVerifier` (implemented with `jose` and Auth0's JWKS), keeping this class focused on the protocol and the mapping.

```typescript
export interface IdTokenVerifier {
  verify(idToken: string, audience: string, issuer: string): Promise<Record<string, unknown> | null>;
}

export interface Auth0Config {
  readonly domain: string; // tenant.eu.auth0.com
  readonly clientId: string;
  readonly clientSecret: string;
}

type PostForm = (url: string, form: Record<string, string>) => Promise<{ status: number; body: unknown }>;

async function sha256Base64Url(text: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return btoa(String.fromCharCode(...new Uint8Array(digest))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function stringClaim(claims: Record<string, unknown>, name: string): string | null {
  const value = claims[name];
  return typeof value === 'string' ? value : null;
}

export class Auth0IdentityProvider implements IdentityProvider {
  constructor(private readonly config: Auth0Config, private readonly post: PostForm, private readonly verifier: IdTokenVerifier) {}

  async authorizationUrl(challenge: LoginChallenge, redirectUri: string): Promise<string> {
    const params = new URLSearchParams({
      response_type: 'code',
      client_id: this.config.clientId,
      redirect_uri: redirectUri,
      scope: 'openid profile email',
      state: challenge.state,
      code_challenge: await sha256Base64Url(challenge.codeVerifier),
      code_challenge_method: 'S256',
    });
    return `https://${this.config.domain}/authorize?${params.toString()}`;
  }

  async complete(
    challenge: LoginChallenge,
    callback: { code: string; state: string },
    redirectUri: string,
  ): Promise<Result<VerifiedIdentity, IdentityError>> {
    if (callback.state !== challenge.state) return Result.fail({ kind: 'StateMismatch' });

    let res: { status: number; body: unknown };
    try {
      res = await this.post(`https://${this.config.domain}/oauth/token`, {
        grant_type: 'authorization_code',
        client_id: this.config.clientId,
        client_secret: this.config.clientSecret,
        code: callback.code,
        code_verifier: challenge.codeVerifier,
        redirect_uri: redirectUri,
      });
    } catch (e: unknown) {
      return Result.fail({ kind: 'ProviderUnavailable', detail: e instanceof Error ? e.message : String(e) });
    }

    const body = typeof res.body === 'object' && res.body !== null ? res.body : {};
    if (res.status >= 500) return Result.fail({ kind: 'ProviderUnavailable', detail: `HTTP ${res.status}` });
    if (res.status !== 200) return Result.fail({ kind: 'CodeRejected', reason: String(Reflect.get(body, 'error') ?? res.status) });

    const idToken: unknown = Reflect.get(body, 'id_token');
    if (typeof idToken !== 'string') return Result.fail({ kind: 'InvalidToken', reason: 'missing id_token' });

    const claims = await this.verifier.verify(idToken, this.config.clientId, `https://${this.config.domain}/`);
    const subject = claims ? stringClaim(claims, 'sub') : null;
    if (!claims || !subject) return Result.fail({ kind: 'InvalidToken', reason: 'signature or claims invalid' });

    const contact = claims['email_verified'] === true ? stringClaim(claims, 'email') : null;
    return Result.ok({
      provider: 'auth0',
      subject,
      contact,
      displayName: stringClaim(claims, 'name') ?? stringClaim(claims, 'nickname') ?? subject,
    });
  }
}
```

Mapping decisions made here, not in the use case:
- An **unverified** address is dropped (`contact: null`), so nobody can claim an existing account by registering the same address at the provider.
- Auth0's error codes (`invalid_grant`, ...) become `CodeRejected`; 5xx and network failures become `ProviderUnavailable`, which the UI shows as "try again" rather than "login failed".

An Okta adapter implements the same interface with its own endpoints and claim names.

### 3. Fake provider for local development
```typescript
export class DevIdentityProvider implements IdentityProvider {
  constructor(private readonly identity: VerifiedIdentity) {}

  async authorizationUrl(challenge: LoginChallenge, redirectUri: string): Promise<string> {
    return `${redirectUri}?code=dev&state=${encodeURIComponent(challenge.state)}`;
  }

  async complete(challenge: LoginChallenge, callback: { code: string; state: string }): Promise<Result<VerifiedIdentity, IdentityError>> {
    if (callback.state !== challenge.state) return Result.fail({ kind: 'StateMismatch' });
    return Result.ok(this.identity);
  }
}
```

It redirects straight back to the callback, so the full login flow, including the state check, runs locally without an Auth0 tenant. Register it only when `NODE_ENV === 'development'`.

```typescript
// Domain/Errors/ValidationError.ts
export class ValidationError {
  constructor(public readonly message: string) {}
}

// Domain/ValueObjects/Email.ts
import { Result, ok, error } from '../Result';
import { ValidationError } from '../Errors/ValidationError';

export class Email {
  private constructor(public readonly value: string) {}

  static create(email: string): Result<Email, ValidationError> {
    // Check if email is empty or null
    if (!email || typeof email !== 'string') {
      return error(new ValidationError('Email must be a non-empty string'));
    }

    // Check if email is non-empty after trimming
    const trimmedEmail = email.trim();
    if (trimmedEmail.length === 0) {
      return error(new ValidationError('Email cannot be empty'));
    }

    // Normalize to lowercase
    const normalizedEmail = trimmedEmail.toLowerCase();

    // Validate email format using regex
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(normalizedEmail)) {
      return error(new ValidationError('Email format is invalid'));
    }

    return ok(new Email(normalizedEmail));
  }

  equals(other: Email): boolean {
    return this.value === other.value;
  }

  toString(): string {
    return this.value;
  }
}

// Domain/Result.ts
export type Result<T, E> = Success<T> | Failure<E>;

interface Success<T> {
  readonly isSuccess: true;
  readonly value: T;
  readonly error?: never;
}

interface Failure<E> {
  readonly isSuccess: false;
  readonly value?: never;
  readonly error: E;
}

export function ok<T>(value: T): Result<T, never> {
  return { isSuccess: true, value };
}

export function error<E>(error: E): Result<never, E> {
  return { isSuccess: false, error };
}
```

This implementation follows Clean Architecture principles with:

1. **Pure Value Object**: The `Email` class is immutable and represents a value with no identity
2. **Invariant Validation**:
   - Ensures email is a non-empty string
   - Validates email format using regex
   - Normalizes to lowercase
   - Trims whitespace
3. **Result Pattern**: Returns `Result<Email, ValidationError>` for safe error handling
4. **No External Dependencies**: The domain layer doesn't depend on any frameworks or infrastructure
5. **Typed Errors**: Uses `ValidationError` for specific error handling
6. **Strict Types**: No `any` types used; all types are explicitly defined
7. **Dependency Rule Compliance**: Domain layer is completely independent of external libraries

The `Email` value object enforces invariants through its factory method `create()` which validates all constraints before creating an instance. The validation includes:
- Non-empty string check
- Format validation using regex
- Lowercase normalization
- Whitespace trimming

The Result pattern ensures that validation failures are explicitly handled and cannot be ignored.

Standings are derived data: instead of updating counters incrementally (and risking drift), the domain recomputes the table from all recorded results. For a league season that is a few hundred matches at most, so it is cheap.

### Domain (`src/domain/league.ts`)
```typescript
import { Result } from '../shared/Result';

export type Outcome =
  | { kind: 'Score'; homeGoals: number; awayGoals: number }
  | { kind: 'Forfeit'; forfeitingTeamId: string };

export interface PlayedMatch {
  readonly homeId: string;
  readonly awayId: string;
  readonly homeGoals: number;
  readonly awayGoals: number;
}

export interface StandingRow {
  readonly teamId: string;
  readonly name: string;
  played: number;
  won: number;
  drawn: number;
  lost: number;
  goalsFor: number;
  goalsAgainst: number;
  points: number;
}

export type MatchError =
  | { kind: 'MatchNotFound' }
  | { kind: 'AlreadyRecorded' }
  | { kind: 'InvalidScore' }
  | { kind: 'ForfeitByOutsider'; teamId: string };

export const FORFEIT_GOALS = 3;

export class ScheduledMatch {
  constructor(
    readonly id: string,
    readonly leagueId: string,
    readonly homeId: string,
    readonly awayId: string,
    private result: PlayedMatch | null,
  ) {}

  get played(): PlayedMatch | null { return this.result; }

  record(outcome: Outcome): Result<PlayedMatch, MatchError> {
    if (this.result) return Result.fail({ kind: 'AlreadyRecorded' });
    let homeGoals: number;
    let awayGoals: number;
    if (outcome.kind === 'Forfeit') {
      if (outcome.forfeitingTeamId !== this.homeId && outcome.forfeitingTeamId !== this.awayId) {
        return Result.fail({ kind: 'ForfeitByOutsider', teamId: outcome.forfeitingTeamId });
      }
      const homeForfeits = outcome.forfeitingTeamId === this.homeId;
      homeGoals = homeForfeits ? 0 : FORFEIT_GOALS;
      awayGoals = homeForfeits ? FORFEIT_GOALS : 0;
    } else {
      const valid = (g: number) => Number.isInteger(g) && g >= 0;
      if (!valid(outcome.homeGoals) || !valid(outcome.awayGoals)) return Result.fail({ kind: 'InvalidScore' });
      homeGoals = outcome.homeGoals;
      awayGoals = outcome.awayGoals;
    }
    this.result = { homeId: this.homeId, awayId: this.awayId, homeGoals, awayGoals };
    return Result.ok(this.result);
  }
}

function apply(row: StandingRow, scored: number, conceded: number): void {
  row.played += 1;
  row.goalsFor += scored;
  row.goalsAgainst += conceded;
  if (scored > conceded) { row.won += 1; row.points += 3; }
  else if (scored === conceded) { row.drawn += 1; row.points += 1; }
  else { row.lost += 1; }
}

export function computeStandings(teams: ReadonlyMap<string, string>, matches: readonly PlayedMatch[]): StandingRow[] {
  const rows = new Map<string, StandingRow>();
  for (const [teamId, name] of teams) {
    rows.set(teamId, { teamId, name, played: 0, won: 0, drawn: 0, lost: 0, goalsFor: 0, goalsAgainst: 0, points: 0 });
  }
  for (const m of matches) {
    const home = rows.get(m.homeId);
    const away = rows.get(m.awayId);
    if (home) apply(home, m.homeGoals, m.awayGoals);
    if (away) apply(away, m.awayGoals, m.homeGoals);
  }
  const diff = (r: StandingRow) => r.goalsFor - r.goalsAgainst;
  return [...rows.values()].sort(
    (a, b) => b.points - a.points || diff(b) - diff(a) || b.goalsFor - a.goalsFor || a.name.localeCompare(b.name),
  );
}
```

### Application (`src/application/RecordMatchResult.ts`)
```typescript
import { Result } from '../shared/Result';
import { MatchError, Outcome, PlayedMatch, ScheduledMatch, StandingRow, computeStandings } from '../domain/league';

export interface MatchRepository {
  findInLeague(leagueId: string, matchId: string): Promise<ScheduledMatch | null>;
  save(match: ScheduledMatch): Promise<void>;
  playedInLeague(leagueId: string): Promise<readonly PlayedMatch[]>;
}

export interface TeamDirectory {
  namesInLeague(leagueId: string): Promise<ReadonlyMap<string, string>>;
}

export class RecordMatchResult {
  constructor(private readonly matches: MatchRepository, private readonly teams: TeamDirectory) {}

  async execute(leagueId: string, matchId: string, outcome: Outcome): Promise<Result<StandingRow[], MatchError>> {
    const match = await this.matches.findInLeague(leagueId, matchId);
    if (!match) return Result.fail({ kind: 'MatchNotFound' });

    const recorded = match.record(outcome);
    if (!recorded.success) return recorded;
    await this.matches.save(match);

    const [names, played] = await Promise.all([this.teams.namesInLeague(leagueId), this.matches.playedInLeague(leagueId)]);
    return Result.ok(computeStandings(names, played));
  }
}
```
Looking the match up by league and id together covers "the match must belong to the league" without a separate check. Two teams level on 10 points with goal difference +4 are separated by goals scored, and only then by name.

How would you unit test this shift swap? Give me the test file, AAA layout, hand-written fakes rather than mocking libraries for the roster, and a fixed "now".

```typescript
import { Result } from '../shared/Result';

export interface Shift {
  id: string;
  employeeId: string;
  role: 'cashier' | 'cook' | 'driver';
  startsAt: Date;
}

export interface Roster {
  shift(id: string): Promise<Shift | null>;
  saveAll(shifts: Shift[]): Promise<void>;
}

export type SwapError =
  | { kind: 'ShiftNotFound'; shiftId: string }
  | { kind: 'SameEmployee' }
  | { kind: 'RoleMismatch' }
  | { kind: 'TooLate'; hoursBeforeStart: number };

const MIN_NOTICE_HOURS = 24;

export class SwapShifts {
  constructor(private readonly roster: Roster, private readonly now: () => Date) {}

  async execute(firstId: string, secondId: string): Promise<Result<void, SwapError>> {
    const first = await this.roster.shift(firstId);
    if (!first) return Result.fail({ kind: 'ShiftNotFound', shiftId: firstId });
    const second = await this.roster.shift(secondId);
    if (!second) return Result.fail({ kind: 'ShiftNotFound', shiftId: secondId });
    if (first.employeeId === second.employeeId) return Result.fail({ kind: 'SameEmployee' });
    if (first.role !== second.role) return Result.fail({ kind: 'RoleMismatch' });
    const earliest = Math.min(first.startsAt.getTime(), second.startsAt.getTime());
    const hoursBeforeStart = (earliest - this.now().getTime()) / 3_600_000;
    if (hoursBeforeStart < MIN_NOTICE_HOURS) return Result.fail({ kind: 'TooLate', hoursBeforeStart });
    await this.roster.saveAll([
      { ...first, employeeId: second.employeeId },
      { ...second, employeeId: first.employeeId },
    ]);
    return Result.ok(undefined);
  }
}
```

I would test it through the public `execute` only, with a `Roster` fake that stores shifts by id. A `shift()` factory builds valid cashier shifts three days ahead; the notice rule is checked on both sides of 24 hours and on the earlier of the two shifts.

```typescript
import { describe, it, expect, beforeEach } from 'vitest';
import { SwapShifts, Roster, Shift } from './SwapShifts';

class InMemoryRoster implements Roster {
  readonly shifts = new Map<string, Shift>();
  saveCalls = 0;
  add(...shifts: Shift[]): void {
    shifts.forEach((s) => this.shifts.set(s.id, s));
  }
  async shift(id: string): Promise<Shift | null> {
    return this.shifts.get(id) ?? null;
  }
  async saveAll(shifts: Shift[]): Promise<void> {
    this.saveCalls += 1;
    this.add(...shifts);
  }
}

const NOW = new Date('2024-04-01T08:00:00Z');
const inHours = (h: number): Date => new Date(NOW.getTime() + h * 3_600_000);
const shift = (id: string, employeeId: string, overrides: Partial<Shift> = {}): Shift => ({
  id, employeeId, role: 'cashier', startsAt: inHours(72), ...overrides,
});

describe('SwapShifts', () => {
  let roster: InMemoryRoster;
  let useCase: SwapShifts;

  beforeEach(() => {
    roster = new InMemoryRoster();
    useCase = new SwapShifts(roster, () => NOW);
  });

  it('exchanges the employees of two compatible shifts', async () => {
    // Arrange
    roster.add(shift('s1', 'ana'), shift('s2', 'ben', { startsAt: inHours(96) }));

    // Act
    const result = await useCase.execute('s1', 's2');

    // Assert
    expect(result.success).toBe(true);
    expect(roster.shifts.get('s1')?.employeeId).toBe('ben');
    expect(roster.shifts.get('s2')?.employeeId).toBe('ana');
  });

  it.each([
    { hours: 24, ok: true },
    { hours: 23.5, ok: false },
  ])('earliest shift $hours h away -> allowed: $ok', async ({ hours, ok }) => {
    // Arrange: only the earlier shift is close to now
    roster.add(shift('s1', 'ana', { startsAt: inHours(hours) }), shift('s2', 'ben'));

    // Act
    const result = await useCase.execute('s1', 's2');

    // Assert
    expect(result.success).toBe(ok);
    if (!result.success) expect(result.error).toEqual({ kind: 'TooLate', hoursBeforeStart: hours });
  });

  it.each(['s1', 's2'])('reports %s as not found when it is missing', async (missing) => {
    // Arrange
    roster.add(shift(missing === 's1' ? 's2' : 's1', 'ana'));

    // Act
    const result = await useCase.execute('s1', 's2');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error).toEqual({ kind: 'ShiftNotFound', shiftId: missing });
  });

  it('rejects swapping two shifts of the same employee', async () => {
    // Arrange
    roster.add(shift('s1', 'ana'), shift('s2', 'ana'));

    // Act
    const result = await useCase.execute('s1', 's2');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('SameEmployee');
  });

  it('rejects shifts with different roles and saves nothing', async () => {
    // Arrange
    roster.add(shift('s1', 'ana'), shift('s2', 'ben', { role: 'cook' }));

    // Act
    const result = await useCase.execute('s1', 's2');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('RoleMismatch');
    expect(roster.saveCalls).toBe(0);
  });
});
