The class is the aggregate: it owns the roster, the capacity and the waitlist order, so all placement rules live there. The use case only checks the duplicate application across classes and persists.

#### 1. Domain (`src/domain/KindergartenClass.ts`)
```typescript
import { Result } from '../shared/Result';

export interface Child {
  readonly id: string;
  readonly birthDate: Date;
  readonly familyId: string;
}

export interface WaitlistEntry {
  readonly childId: string;
  readonly sibling: boolean;
}

export type Placement = { kind: 'Enrolled' } | { kind: 'Waitlisted'; position: number };

export type EnrollmentError =
  | { kind: 'ClassNotFound' }
  | { kind: 'ChildNotFound' }
  | { kind: 'TooYoung'; cutoff: Date }
  | { kind: 'AlreadyApplied' };

export const MIN_AGE_YEARS = 5;

export function ageCutoff(schoolYear: number): Date {
  return new Date(Date.UTC(schoolYear, 8, 1)); // September 1
}

export function isOldEnough(birthDate: Date, schoolYear: number): boolean {
  const fifthBirthday = new Date(Date.UTC(
    birthDate.getUTCFullYear() + MIN_AGE_YEARS, birthDate.getUTCMonth(), birthDate.getUTCDate(),
  ));
  return fifthBirthday <= ageCutoff(schoolYear);
}

export class KindergartenClass {
  constructor(
    readonly id: string,
    readonly schoolYear: number,
    readonly capacity: number,
    private readonly enrolled: Child[],
    private readonly waitlist: WaitlistEntry[],
  ) {}

  get roster(): readonly Child[] { return this.enrolled; }
  get queue(): readonly WaitlistEntry[] { return this.waitlist; }

  place(child: Child): Result<Placement, EnrollmentError> {
    if (!isOldEnough(child.birthDate, this.schoolYear)) {
      return Result.fail({ kind: 'TooYoung', cutoff: ageCutoff(this.schoolYear) });
    }
    if (this.enrolled.length < this.capacity) {
      this.enrolled.push(child);
      return Result.ok({ kind: 'Enrolled' });
    }
    const sibling = this.enrolled.some((c) => c.familyId === child.familyId);
    const index = sibling ? this.waitlist.filter((e) => e.sibling).length : this.waitlist.length;
    this.waitlist.splice(index, 0, { childId: child.id, sibling });
    return Result.ok({ kind: 'Waitlisted', position: index + 1 });
  }
}
```
Because siblings are always inserted right after the last sibling, the waitlist stays partitioned (all siblings first), so counting the sibling entries gives the insertion index.

#### 2. Application (`src/application/EnrollChild.ts`)
```typescript
import { Result } from '../shared/Result';
import { Child, EnrollmentError, KindergartenClass, Placement } from '../domain/KindergartenClass';

export interface ClassRepository {
  findById(id: string): Promise<KindergartenClass | null>;
  save(kgClass: KindergartenClass): Promise<void>;
}

export interface ChildDirectory {
  findById(id: string): Promise<Child | null>;
}

export interface ApplicationIndex {
  hasApplication(childId: string, schoolYear: number): Promise<boolean>;
}

export class EnrollChild {
  constructor(
    private readonly classes: ClassRepository,
    private readonly children: ChildDirectory,
    private readonly applications: ApplicationIndex,
  ) {}

  async execute(classId: string, childId: string): Promise<Result<Placement, EnrollmentError>> {
    const kgClass = await this.classes.findById(classId);
    if (!kgClass) return Result.fail({ kind: 'ClassNotFound' });
    const child = await this.children.findById(childId);
    if (!child) return Result.fail({ kind: 'ChildNotFound' });
    if (await this.applications.hasApplication(child.id, kgClass.schoolYear)) {
      return Result.fail({ kind: 'AlreadyApplied' });
    }

    const placed = kgClass.place(child);
    if (!placed.success) return placed;
    await this.classes.save(kgClass);
    return placed;
  }
}
```
`ApplicationIndex` covers every class in the school, since a child waitlisted in class A must not apply to class B the same year. The repository must save the class with optimistic locking, otherwise two parents could take the last seat at the same time.

The tariff and the consumption rules are pure arithmetic over the account and the reading, so they live in the domain with integer cents and whole kWh. The use case loads the account, saves the bill and the advanced account together.

#### 1. Domain (`src/domain/billing.ts`)
```typescript
import { Result } from '../shared/Result';

export interface MeterAccount {
  readonly accountId: string;
  readonly lastReadingKwh: number;
  readonly lastReadOn: Date;
}

export interface NewReading {
  readonly valueKwh: number;
  readonly readOn: Date;
  readonly replacedMeterFinalKwh?: number;
}

export interface Bill {
  readonly accountId: string;
  readonly from: Date;
  readonly to: Date;
  readonly days: number;
  readonly consumptionKwh: number;
  readonly energyCents: number;
  readonly serviceCents: number;
  readonly totalCents: number;
}

export type BillingError =
  | { kind: 'AccountNotFound' }
  | { kind: 'InvalidPeriod'; days: number }
  | { kind: 'NegativeConsumption' };

const DAY_MS = 86_400_000;
export const MIN_DAYS = 27;
export const MAX_DAYS = 33;
const TIERS: readonly { upToKwh: number; cents: number }[] = [
  { upToKwh: 100, cents: 12 },
  { upToKwh: 500, cents: 15 },
  { upToKwh: Infinity, cents: 20 },
];
export const SERVICE_CENTS_PER_DAY = 30;

export function consumption(account: MeterAccount, reading: NewReading): number {
  return reading.replacedMeterFinalKwh === undefined
    ? reading.valueKwh - account.lastReadingKwh
    : reading.replacedMeterFinalKwh - account.lastReadingKwh + reading.valueKwh;
}

export function energyCharge(kwh: number, days: number): number {
  let cents = 0;
  let lower = 0;
  for (const tier of TIERS) {
    const upper = tier.upToKwh === Infinity ? Infinity : Math.round((tier.upToKwh * days) / 30);
    const inTier = Math.max(0, Math.min(kwh, upper) - lower);
    cents += inTier * tier.cents;
    lower = upper;
  }
  return cents;
}

export function closePeriod(account: MeterAccount, reading: NewReading): Result<Bill, BillingError> {
  const days = Math.round((reading.readOn.getTime() - account.lastReadOn.getTime()) / DAY_MS);
  if (days < MIN_DAYS || days > MAX_DAYS) return Result.fail({ kind: 'InvalidPeriod', days });

  const kwh = consumption(account, reading);
  if (kwh < 0) return Result.fail({ kind: 'NegativeConsumption' });

  const energyCents = energyCharge(kwh, days);
  const serviceCents = days * SERVICE_CENTS_PER_DAY;
  return Result.ok({
    accountId: account.accountId,
    from: account.lastReadOn,
    to: reading.readOn,
    days,
    consumptionKwh: kwh,
    energyCents,
    serviceCents,
    totalCents: energyCents + serviceCents,
  });
}
```

#### 2. Application (`src/application/CloseBillingPeriod.ts`)
```typescript
import { Result } from '../shared/Result';
import { Bill, BillingError, MeterAccount, NewReading, closePeriod } from '../domain/billing';

export interface MeterAccountRepository {
  findById(accountId: string): Promise<MeterAccount | null>;
}

export interface BillingStore {
  // Saves the bill and the advanced account atomically.
  commit(bill: Bill, account: MeterAccount): Promise<void>;
}

export class CloseBillingPeriod {
  constructor(private readonly accounts: MeterAccountRepository, private readonly store: BillingStore) {}

  async execute(accountId: string, reading: NewReading): Promise<Result<Bill, BillingError>> {
    const account = await this.accounts.findById(accountId);
    if (!account) return Result.fail({ kind: 'AccountNotFound' });

    const bill = closePeriod(account, reading);
    if (!bill.success) return bill;

    await this.store.commit(bill.data, { accountId, lastReadingKwh: reading.valueKwh, lastReadOn: reading.readOn });
    return bill;
  }
}
```

Worked example: 31 days and 650 kWh scale the limits to 103 and 517 kWh, so energy is 103 × 12 + 414 × 15 + 133 × 20 = 10,106 cents, service is 930 cents, total 110.36. After a meter swap the stored last reading becomes the new meter's value, not the old final reading. `BillingStore.commit` is one database transaction in infrastructure, so a crash cannot leave a bill without the account moving forward (or the reverse).

```typescript
// Domain/Errors/ValidationError.ts
export class ValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ValidationError";
  }
}

// Domain/ValueObjects/Email.ts
import { Result, ok, err } from "../Result";
import { ValidationError } from "../Errors/ValidationError";

export class Email {
  private constructor(private readonly value: string) {
    // Private constructor to enforce creation through static factory method
  }

  // Factory method with validation
  static create(email: string): Result<Email, ValidationError> {
    // Check if email is empty or null
    if (!email || typeof email !== 'string') {
      return err(new ValidationError("Email cannot be empty or null"));
    }

    // Check if email is non-empty after trimming
    const trimmedEmail = email.trim();
    if (trimmedEmail.length === 0) {
      return err(new ValidationError("Email cannot be empty"));
    }

    // Normalize to lowercase
    const normalizedEmail = trimmedEmail.toLowerCase();

    // Validate email format using regex
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(normalizedEmail)) {
      return err(new ValidationError("Email format is invalid"));
    }

    // Create and return the Email value object
    return ok(new Email(normalizedEmail));
  }

  // Getter for the email value
  getValue(): string {
    return this.value;
  }

  // Equality check
  equals(other: Email): boolean {
    return this.value === other.getValue();
  }

  // String representation
  toString(): string {
    return this.value;
  }
}

// Result type definition (if not already available)
export type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

export function ok<T, E>(value: T): Result<T, E> {
  return { ok: true, value };
}

export function err<T, E>(error: E): Result<T, E> {
  return { ok: false, error };
}
```

This implementation follows Clean Architecture principles:

1. **Pure Value Object**: The `Email` class is immutable and represents a value with no identity
2. **Invariant Validation**:
   - Ensures email is not empty or null
   - Validates email format using regex
   - Normalizes to lowercase
3. **Dependency Rule Compliance**: 
   - Domain layer (Email) doesn't depend on external libraries
   - Uses only native JavaScript/TypeScript features
4. **Result Pattern**: Returns `Result<Email, ValidationError>` for proper error handling
5. **SOLID Principles**:
   - Single Responsibility: Email class only handles email validation and representation
   - Open/Closed: Can be extended but not modified
   - Liskov Substitution: Email objects can be used wherever a string is expected (via getValue())
   - Interface Segregation: Minimal interface exposed
   - Dependency Inversion: Depends on abstractions (ValidationError, Result)

The factory method `create()` enforces all invariants and returns either a valid `Email` object or a `ValidationError` wrapped in a `Result` type.

This Redux thunk applies gift cards at checkout. Restructure it so the redemption logic is independent of Redux and fetch:

```typescript
export const applyGiftCards = (codes: string[]) => async (dispatch: AppDispatch, getState: () => RootState) => {
  let due = getState().checkout.totalCents;
  const applied: { code: string; usedCents: number }[] = [];
  for (const code of codes.slice(0, 3)) {
    const res = await fetch(`/api/gift-cards/${encodeURIComponent(code)}`);
    if (!res.ok) { dispatch(checkoutError(`Gift card ${code} not found`)); return; }
    const card = await res.json();
    if (card.currency !== getState().checkout.currency) { dispatch(checkoutError('Currency mismatch')); return; }
    if (new Date(card.expiresOn) < new Date()) continue;
    const used = Math.min(card.balanceCents, due);
    if (used > 0) applied.push({ code, usedCents: used });
    due -= used;
    if (due === 0) break;
  }
  dispatch(giftCardsApplied({ applied, remainingCents: due }));
};
```

### Architectural Flaws in Original Code
1. **Redemption rules inside a thunk:** the three-card limit, currency check, expiry skip and balance allocation are tied to Redux.
2. **HTTP in the state layer:** `fetch` and the URL format are mixed with business decisions.
3. **Untyped card payload:** `res.json()` is trusted without a shape check.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/giftCards.ts`)
```typescript
import { Result } from '../shared/Result';

export interface GiftCard {
  readonly code: string;
  readonly balanceCents: number;
  readonly currency: string;
  readonly expiresOn: Date;
}

export interface Allocation {
  readonly applied: readonly { code: string; usedCents: number }[];
  readonly remainingCents: number;
}

export type GiftCardError = { kind: 'NotFound'; code: string } | { kind: 'CurrencyMismatch'; code: string };

export const MAX_CARDS = 3;

/** Spends cards in order until the amount is covered; expired cards are skipped. */
export function allocate(
  cards: readonly GiftCard[], dueCents: number, currency: string, today: Date,
): Result<Allocation, GiftCardError> {
  let remaining = dueCents;
  const applied: { code: string; usedCents: number }[] = [];
  for (const card of cards) {
    if (card.currency !== currency) return Result.fail({ kind: 'CurrencyMismatch', code: card.code });
    if (card.expiresOn < today) continue;
    const used = Math.min(card.balanceCents, remaining);
    if (used > 0) applied.push({ code: card.code, usedCents: used });
    remaining -= used;
    if (remaining === 0) break;
  }
  return Result.ok({ applied, remainingCents: remaining });
}
```

#### 2. Application Layer (`src/application/ApplyGiftCards.ts`)
Cards are looked up in order, so a missing card is reported only if it would have been reached before the total was covered.
```typescript
import { Result } from '../shared/Result';
import { Allocation, GiftCard, GiftCardError, MAX_CARDS, allocate } from '../domain/giftCards';

export interface GiftCardLookup {
  find(code: string): Promise<GiftCard | null>;
}

export class ApplyGiftCards {
  constructor(private readonly lookup: GiftCardLookup, private readonly today: () => Date) {}

  async execute(codes: readonly string[], dueCents: number, currency: string): Promise<Result<Allocation, GiftCardError>> {
    const cards: GiftCard[] = [];
    for (const code of codes.slice(0, MAX_CARDS)) {
      const card = await this.lookup.find(code);
      if (!card) return Result.fail({ kind: 'NotFound', code });
      cards.push(card);
      const partial = allocate(cards, dueCents, currency, this.today());
      if (!partial.success || partial.data.remainingCents === 0) return partial;
    }
    return allocate(cards, dueCents, currency, this.today());
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/HttpGiftCardLookup.ts`)
```typescript
import { GiftCard } from '../domain/giftCards';
import { GiftCardLookup } from '../application/ApplyGiftCards';

interface GiftCardDto { balanceCents: number; currency: string; expiresOn: string; }

function isGiftCardDto(v: unknown): v is GiftCardDto {
  if (typeof v !== 'object' || v === null) return false;
  const d = v as Record<string, unknown>;
  return typeof d.balanceCents === 'number' && typeof d.currency === 'string' && typeof d.expiresOn === 'string';
}

export class HttpGiftCardLookup implements GiftCardLookup {
  async find(code: string): Promise<GiftCard | null> {
    const res = await fetch(`/api/gift-cards/${encodeURIComponent(code)}`);
    if (!res.ok) return null;
    const body: unknown = await res.json();
    if (!isGiftCardDto(body)) return null;
    return { code, balanceCents: body.balanceCents, currency: body.currency, expiresOn: new Date(body.expiresOn) };
  }
}
```

#### 4. Presentation Layer (thin thunk)
```typescript
