// Domain/Errors/ValidationError.ts
export class ValidationError {
  constructor(public readonly message: string) {}
}

// Domain/ValueObjects/Email.ts
import { Result, ok, error } from '../Result';
import { ValidationError } from '../Errors/ValidationError';

export class Email {
  private constructor(public readonly value: string) {}

  static create(email: string): Result<Email, ValidationError> {
    // Check if email is empty or null
    if (!email || typeof email !== 'string') {
      return error(new ValidationError('Email must be a non-empty string'));
    }

    // Check if email is not empty after trimming
    const trimmedEmail = email.trim();
    if (trimmedEmail.length === 0) {
      return error(new ValidationError('Email cannot be empty'));
    }

    // Normalize to lowercase
    const normalizedEmail = trimmedEmail.toLowerCase();

    // Validate email format using regex
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(normalizedEmail)) {
      return error(new ValidationError('Email format is invalid'));
    }

    // Create and return the Email value object
    return ok(new Email(normalizedEmail));
  }

  equals(other: Email): boolean {
    return this.value === other.value;
  }

  toString(): string {
    return this.value;
  }
}

// Domain/Result.ts
export type Result<T, E> = Success<T> | Failure<E>;

interface Success<T> {
  readonly isSuccess: true;
  readonly value: T;
  readonly error?: never;
}

interface Failure<E> {
  readonly isSuccess: false;
  readonly value?: never;
  readonly error: E;
}

export function ok<T>(value: T): Result<T, never> {
  return { isSuccess: true, value };
}

export function error<E>(error: E): Result<never, E> {
  return { isSuccess: false, error };
}
```

This implementation follows Clean Architecture principles with:

1. **Pure Value Object**: The `Email` class is immutable and represents a value with no identity
2. **Invariant Validation**:
   - Ensures email is a non-empty string
   - Validates email format using regex
   - Normalizes to lowercase
   - Trims whitespace
3. **Result Pattern**: Returns `Result<Email, ValidationError>` for proper error handling
4. **Dependency Rule Compliance**: 
   - Domain layer (Email, ValidationError) doesn't depend on external libraries
   - No framework or infrastructure dependencies
5. **Typed Errors**: Uses dedicated `ValidationError` class instead of generic errors
6. **No `any` Type**: All types are strictly defined with interfaces and generics

The `Email` value object enforces invariants through its factory method `create()` which validates all constraints before creating an instance. The validation includes:
- Non-empty string check
- Format validation using regex
- Lowercase normalization
- Whitespace trimming

The Result pattern ensures proper error handling without throwing exceptions, making the domain layer pure and testable.

Write unit tests for `RenewDomain`, including the redemption period and the ten-year cap. Use a billing fake that can be told to decline and a fixed clock.

```typescript
import { Result } from '../shared/Result';

export interface Registration {
  name: string;
  ownerId: string;
  expiresAt: Date;
}

export interface RegistrationRepository {
  find(name: string): Promise<Registration | null>;
  save(registration: Registration): Promise<void>;
}

export interface BillingAccount {
  charge(customerId: string, cents: number): Promise<boolean>;
}

export type RenewError =
  | { kind: 'InvalidYears' }
  | { kind: 'NotRegistered' }
  | { kind: 'InRedemption' }
  | { kind: 'ExceedsMaxTerm' }
  | { kind: 'PaymentDeclined' };

const PRICE_PER_YEAR_CENTS = 1_299;
const MAX_YEARS = 10;
const REDEMPTION_MS = 30 * 86_400_000;

const addYears = (date: Date, years: number): Date => {
  const copy = new Date(date);
  copy.setUTCFullYear(copy.getUTCFullYear() + years);
  return copy;
};

export class RenewDomain {
  constructor(
    private readonly registrations: RegistrationRepository,
    private readonly billing: BillingAccount,
    private readonly now: () => Date,
  ) {}

  async execute(name: string, years: number): Promise<Result<Date, RenewError>> {
    if (!Number.isInteger(years) || years < 1) return Result.fail({ kind: 'InvalidYears' });
    const reg = await this.registrations.find(name);
    if (!reg) return Result.fail({ kind: 'NotRegistered' });
    const now = this.now();
    if (now.getTime() - reg.expiresAt.getTime() > REDEMPTION_MS) return Result.fail({ kind: 'InRedemption' });
    const expiresAt = addYears(reg.expiresAt, years);
    if (expiresAt > addYears(now, MAX_YEARS)) return Result.fail({ kind: 'ExceedsMaxTerm' });
    const paid = await this.billing.charge(reg.ownerId, years * PRICE_PER_YEAR_CENTS);
    if (!paid) return Result.fail({ kind: 'PaymentDeclined' });
    await this.registrations.save({ ...reg, expiresAt });
    return Result.ok(expiresAt);
  }
}
```

The billing fake records charges and has a `declines` switch for the declined path. Dates are UTC, relative to a clock frozen at 1 Jan 2025.

```typescript
import { describe, it, expect, beforeEach } from 'vitest';
import { RenewDomain, BillingAccount, Registration, RegistrationRepository } from './RenewDomain';

class InMemoryRegistrations implements RegistrationRepository {
  readonly byName = new Map<string, Registration>();
  async find(name: string): Promise<Registration | null> {
    return this.byName.get(name) ?? null;
  }
  async save(registration: Registration): Promise<void> {
    this.byName.set(registration.name, registration);
  }
}

class FakeBilling implements BillingAccount {
  declines = false;
  readonly charges: Array<{ customerId: string; cents: number }> = [];
  async charge(customerId: string, cents: number): Promise<boolean> {
    if (this.declines) return false;
    this.charges.push({ customerId, cents });
    return true;
  }
}

const NOW = new Date('2025-01-01T00:00:00Z');
