```typescript
import { type IAccountRepository } from '../../domain/repositories/IAccountRepository';
import { type ICryptoService } from '../ports/ICryptoService';
import { Account } from '../../domain/entities/Account';
import { Email } from '../../domain/value-objects/Email';
import { Password } from '../../domain/value-objects/Password';

export interface RegisterAccountRequest {
  email: string;
  passwordPlainText: string;
}

export type RegisterAccountResult =
  | { success: true; accountId: string }
  | { success: false; error: string };

export class RegisterAccount {
  constructor(
    private readonly accountRepository: IAccountRepository,
    private readonly cryptoService: ICryptoService,
    private readonly idGenerator: () => string
  ) {}

  async execute(request: RegisterAccountRequest): Promise<RegisterAccountResult> {
    try {
      // 1. Enforce business invariants using Domain Value Objects
      const email = Email.create(request.email);
      const password = Password.create(request.passwordPlainText);

      // 2. Check for duplicate account
      const existingAccount = await this.accountRepository.findByEmail(email);
      if (existingAccount) {
        return { success: false, error: 'email is already in use' };
      }

      // 3. Hash password via infrastructure port contract
      const passwordHash = await this.cryptoService.hash(password.getValue());

      // 4. Construct and persist domain entity
      const accountId = this.idGenerator();
      const account = new Account(accountId, email, passwordHash);

      await this.accountRepository.save(account);
      return { success: true, accountId };
    } catch (error) {
      return { success: false, error: (error as Error).message };
    }
  }
}
```

### Dependency Analysis:
- **Result Pattern:** Returns an explicit `RegisterAccountResult` discriminated union rather than throwing untyped runtime errors.
- **Ports Inversion:** `ICryptoService` and `IAccountRepository` are interfaces defined inside core layers; the use case does not know if bcrypt, argon2, Postgres, or MongoDB are running.
- **Injected ID Generator:** Avoids coupling to specific UUID libraries in application core.

```typescript
export class ValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ValidationError';
  }
}

export class Password {
  private readonly value: string;
  private static readonly MIN_LENGTH = 8;
  private static readonly HAS_LETTER = /[a-zA-Z]/;
  private static readonly HAS_NUMBER = /[0-9]/;

  private constructor(rawPassword: string) {
    this.value = rawPassword;
  }

  public static create(rawPassword: string): Password {
    if (!rawPassword || rawPassword.trim().length === 0) {
      throw new ValidationError('password cannot be empty');
    }
    if (rawPassword.length < this.MIN_LENGTH) {
      throw new ValidationError(`password must be at least ${this.MIN_LENGTH} characters long`);
    }
    if (!this.HAS_LETTER.test(rawPassword)) {
      throw new ValidationError('password must contain at least one letter');
    }
    if (!this.HAS_NUMBER.test(rawPassword)) {
      throw new ValidationError('password must contain at least one number');
    }
    return new Password(rawPassword);
  }

  public getValue(): string {
    return this.value;
  }

  public toString(): string {
    return '[PROTECTED_PASSWORD]';
  }
}
```

### Architectural Highlights:
1. **Typed Domain Error:** Throws `ValidationError` (same typed error as `EmailAddress`) — both Value Objects share the same error contract, enabling consistent error handling in the application layer.
2. **Zero External Dependencies:** Built with pure TypeScript ECMAScript semantics without third-party validation libraries.
3. **Private Constructor:** Guarantees that an invalid `Password` cannot be instantiated in memory.
4. **Safe String Representation:** `toString()` masks the internal value to avoid leaking secrets in loggers.

Critique this subclass relationship with SOLID, especially Liskov, and fix it:

```typescript
class FileStore {
  save(name: string, data: string): void { /* writes to disk */ }
}
class ReadOnlyFileStore extends FileStore {
  save(name: string, data: string): void {
    throw new Error('Store is read-only');
  }
}
function backup(store: FileStore) {
  store.save('backup.json', '{}');
}
```

### SOLID Critique
- **LSP (violated):** `ReadOnlyFileStore` strengthens the precondition of `save` to "never callable", so `backup(new ReadOnlyFileStore())` throws.
- **ISP (violated):** the base type bundles reading and writing, forcing read-only stores to inherit a method they cannot honor.
- **Inheritance misuse:** the subclass removes behavior instead of extending it.

---

### Refactoring: split read and write contracts
```typescript
export interface FileReader {
  read(name: string): string;
}

export interface FileWriter {
  save(name: string, data: string): void;
}

export class DiskStore implements FileReader, FileWriter {
  read(name: string): string { return ''; /* reads from disk */ }
  save(name: string, data: string): void { /* writes to disk */ }
}

export class ArchiveStore implements FileReader {
  read(name: string): string { return ''; /* reads from an archive */ }
}

export function backup(store: FileWriter): void {
  store.save('backup.json', '{}');
}
```

`backup` now accepts only writers, so passing an `ArchiveStore` is a compile-time error instead of a runtime crash.

