  async execute(quoteId: string, customerId: string): Promise<Result<{ visitId: string; depositCents: number }, AcceptError>> {
    const quote = await this.quotes.get(quoteId);
    if (!quote) return Result.fail({ kind: 'QuoteNotFound' });
    if (quote.customerId !== customerId) return Result.fail({ kind: 'NotYourQuote' });
    if (quote.status !== 'sent') return Result.fail({ kind: 'NotPending', status: quote.status });
    if (this.now().getTime() - quote.issuedAt.getTime() > VALID_MS) return Result.fail({ kind: 'QuoteExpired' });
    const depositCents = Math.round(quote.totalCents * DEPOSIT_RATE);
    const visitId = await this.scheduler.book(quote.id, depositCents);
    await this.quotes.save({ ...quote, status: 'accepted' });
    return Result.ok({ visitId, depositCents });
  }
}
```

Plan: an in-memory quote store, a `vi.fn` scheduler that resolves to a fixed visit id, and a clock frozen at noon on 15 April. The deposit rounding gets its own small table because `Math.round` on 20% is where an off-by-one cent would hide.

```typescript
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { AcceptRepairQuote, QuoteRepository, RepairQuote, TechnicianScheduler } from './AcceptRepairQuote';

class InMemoryQuotes implements QuoteRepository {
  readonly quotes = new Map<string, RepairQuote>();
  async get(id: string): Promise<RepairQuote | null> {
    return this.quotes.get(id) ?? null;
  }
  async save(quote: RepairQuote): Promise<void> {
    this.quotes.set(quote.id, quote);
  }
}

const NOW = new Date('2024-04-15T12:00:00Z');
const daysAgo = (d: number): Date => new Date(NOW.getTime() - d * 86_400_000);
const aQuote = (overrides: Partial<RepairQuote> = {}): RepairQuote => ({
  id: 'q-1', customerId: 'c-1', status: 'sent', totalCents: 25_000, issuedAt: daysAgo(3), ...overrides,
});

describe('AcceptRepairQuote', () => {
  let quotes: InMemoryQuotes;
  let book: ReturnType<typeof vi.fn<TechnicianScheduler['book']>>;
  let useCase: AcceptRepairQuote;

  beforeEach(() => {
    quotes = new InMemoryQuotes();
    book = vi.fn<TechnicianScheduler['book']>().mockResolvedValue('visit-77');
    useCase = new AcceptRepairQuote(quotes, { book }, () => NOW);
  });

  it('accepts the quote, books a visit and returns a 20% deposit', async () => {
    // Arrange
    await quotes.save(aQuote());

    // Act
    const result = await useCase.execute('q-1', 'c-1');

    // Assert
    expect(result).toEqual({ success: true, data: { visitId: 'visit-77', depositCents: 5_000 } });
    expect(book).toHaveBeenCalledWith('q-1', 5_000);
    expect(quotes.quotes.get('q-1')?.status).toBe('accepted');
  });

  it.each([
    { total: 999, deposit: 200 },
    { total: 2_502, deposit: 500 },
    { total: 2_503, deposit: 501 },
  ])('rounds the deposit for $total to $deposit', async ({ total, deposit }) => {
    // Arrange
    await quotes.save(aQuote({ totalCents: total }));

    // Act
    const result = await useCase.execute('q-1', 'c-1');

    // Assert
    expect(result.success).toBe(true);
    if (!result.success) return;
    expect(result.data.depositCents).toBe(deposit);
  });

  it('accepts on day 14 but not after it', async () => {
    // Arrange
    await quotes.save(aQuote({ id: 'q-14', issuedAt: daysAgo(14) }));
    await quotes.save(aQuote({ id: 'q-15', issuedAt: daysAgo(14.01) }));

    // Act
    const onTime = await useCase.execute('q-14', 'c-1');
    const late = await useCase.execute('q-15', 'c-1');

    // Assert
    expect(onTime.success).toBe(true);
    expect(late.success).toBe(false);
    if (late.success) return;
    expect(late.error.kind).toBe('QuoteExpired');
  });

  it('fails with QuoteNotFound', async () => {
    // Arrange: no quotes

    // Act
    const result = await useCase.execute('q-x', 'c-1');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('QuoteNotFound');
  });

  it("refuses another customer's quote without booking", async () => {
    // Arrange
    await quotes.save(aQuote());

    // Act
    const result = await useCase.execute('q-1', 'c-2');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('NotYourQuote');
    expect(book).not.toHaveBeenCalled();
  });

  it('refuses a quote that was already declined', async () => {
    // Arrange
    await quotes.save(aQuote({ status: 'declined' }));

    // Act
    const result = await useCase.execute('q-1', 'c-1');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error).toEqual({ kind: 'NotPending', status: 'declined' });
  });
});
